import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;

public class Birthday {
    static Calendar birthdayC = new GregorianCalendar(2024, Calendar.AUGUST, 10);
    static Calendar todayC = new GregorianCalendar();

    static Date birthday = birthdayC.getTime();
    static Date today = todayC.getTime();

    static SimpleDateFormat dateFormat = new SimpleDateFormat("dd/MM/yyyy");

    public static void HappyBirthday () throws InterruptedException {
        while (dateFormat.format(today).equals(dateFormat.format(birthday))) {
            System.out.println("Пользуясь случаем хочу поздравить @fedoska_t и @Black_WLN с днем рождения");
            Thread.sleep(1000);
        }
    }
}

